    v45 = g.vmath('MULTIPLY', v40, v44)
    v46 = g.comb(v43[2], v42, 0.0)
    v47 = g.vmath('ADD', v45, v46)
    v48 = g.math('MULTIPLY', v4, 1.0)
    v49 = g.comb(v39[2], v6, 0.0)
